\set ON_ERROR_STOP on
begin;
set local statement_timeout = '15s';
do $guard$
begin
  if to_regtype('public.candidate_acquisition_status') is null
    or to_regtype('public.candidate_decision_value') is not null
    or exists(select 1 from public.rooms)
    or exists(select 1 from auth.users)
  then raise exception 'Feature 007 fixture precondition failed'; end if;
end;
$guard$;

insert into auth.users(id)
select ('f7000000-0000-4000-8000-' || lpad(i::text,12,'0'))::uuid
from generate_series(1,16) as i;

