insert into private.room_filter_resolutions(room_id,release_year_from,release_year_to)
select id,2000,2026 from public.rooms
where filter_resolution_status='compatible';
commit;

select jsonb_build_object(
  'rooms',(select jsonb_agg(to_jsonb(r)||jsonb_build_object('row_xmin',xmin::text) order by id) from public.rooms r),
  'members',(select jsonb_agg(to_jsonb(m)||jsonb_build_object('row_xmin',xmin::text) order by id) from public.room_members m),
  'filters',(select coalesce(jsonb_agg(to_jsonb(f)||jsonb_build_object('row_xmin',xmin::text) order by room_member_id),'[]'::jsonb) from public.participant_filters f),
  'parents',(select jsonb_agg(to_jsonb(p)||jsonb_build_object('row_xmin',xmin::text) order by room_id) from private.room_filter_resolutions p),
  'clauses',(select coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('row_xmin',xmin::text) order by room_id,clause_ordinal),'[]'::jsonb) from private.room_filter_resolution_genre_clauses c),
  'candidates',(select jsonb_agg(to_jsonb(c)||jsonb_build_object('row_xmin',xmin::text) order by sort_order) from public.movie_candidates c)
);
